import React, { useState, useEffect } from 'react';
import { 
  fetchHome, fetchProjects, fetchSkills, fetchAbout, fetchContactInfo, sendContactMessage 
} from './services/api';
// Defaulting to a placeholder avatar if not uploaded to Django yet
import zoroAvatar from './assets/zoro.png'; 
// Import generic icons that exist in lucide-react
import { Code2, Share2, Phone, Mail, User, Menu, X } from 'lucide-react'; 

export default function App() {
  const [activeSection, setActiveSection] = useState('home');
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Dynamic Data States from Django CMS
  const [homeData, setHomeData] = useState(null);
  const [projects, setProjects] = useState([]);
  const [skills, setSkills] = useState([]);
  const [aboutData, setAboutData] = useState(null);
  const [contactInfo, setContactInfo] = useState(null);

  // Contact Form State
  const [contactForm, setContactForm] = useState({ name: '', subject: '', message: '' });
  const [submitted, setSubmitted] = useState(false);

  useEffect(() => {
    fetchHome().then(res => setHomeData(res.data)).catch(err => console.error(err));
    fetchProjects().then(res => setProjects(res.data)).catch(err => console.error(err));
    fetchSkills().then(res => setSkills(res.data)).catch(err => console.error(err));
    fetchAbout().then(res => setAboutData(res.data)).catch(err => console.error(err));
    fetchContactInfo().then(res => setContactInfo(res.data)).catch(err => console.error(err));
  }, []);

  const handleContactSubmit = (e) => {
    e.preventDefault();
    sendContactMessage(contactForm).then(() => {
      setSubmitted(true);
      setContactForm({ name: '', subject: '', message: '' });
      setTimeout(() => setSubmitted(false), 5000);
    }).catch(err => console.error(err));
  };

  const scrollToSection = (sectionId) => {
    setActiveSection(sectionId);
    setMobileMenuOpen(false);
    document.getElementById(sectionId)?.scrollIntoView({ behavior: 'smooth' });
  };

  // Helper to safely get image source
  const getProfileImage = () => {
    if (homeData?.profile_image) return homeData.profile_image;
    if (zoroAvatar) return zoroAvatar; // From original import
    return placeholderAvatar; // Fallback
  };

  return (
    <div className="bg-[#0b0b0b] text-white min-h-screen font-sans selection:bg-blue-600 selection:text-white">
      {/* Navbar matching exact layout */}
      <nav className="fixed top-0 left-0 w-full bg-[#121212]/90 backdrop-blur-md z-50 border-b border-gray-800 px-6 md:px-16 py-4 flex justify-between items-center">
        <div className="text-xl font-bold tracking-wide">Personal Portfolio</div>

        {/* Desktop Menu */}
        <div className="hidden md:flex gap-8 text-sm font-medium text-gray-300">
          {['home', 'projects', 'skills', 'about', 'contact'].map((sec) => (
            <button
              key={sec}
              onClick={() => scrollToSection(sec)}
              className={`capitalize transition-colors hover:text-blue-500 ${activeSection === sec ? 'text-blue-500 font-semibold' : ''}`}
            >
              {sec}
            </button>
          ))}
        </div>

        {/* Mobile menu toggle */}
        <div className="md:hidden flex items-center">
          <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)}>
            {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </nav>

      {/* Mobile Drawer */}
      {mobileMenuOpen && (
        <div className="fixed inset-0 bg-[#0b0b0b] z-40 flex flex-col items-center justify-center gap-6 text-xl md:hidden">
          {['home', 'projects', 'skills', 'about', 'contact'].map((sec) => (
            <button
              key={sec}
              onClick={() => scrollToSection(sec)}
              className={`capitalize ${activeSection === sec ? 'text-blue-500 font-bold' : 'text-gray-300'}`}
            >
              {sec}
            </button>
          ))}
        </div>
      )}

      {/* --- 1. HOME SECTION --- */}
      <section id="home" className="min-h-screen flex items-center justify-center pt-24 px-6 md:px-16">
        <div className="max-w-6xl w-full grid grid-cols-1 md:grid-cols-2 gap-12 items-center">
          <div>
            <p className="text-gray-300 text-lg mb-2">{homeData?.title || "Welcome to My Personal Portfolio"}</p>
            <h2 className="text-4xl md:text-5xl font-light mb-2">{homeData?.greeting || "Hello! there"}</h2>
            <h1 className="text-5xl md:text-7xl font-extrabold tracking-wide mb-6">
              I'M <span className="text-[#3b82f6]">{homeData?.name || "Sahil Karki"}</span>
            </h1>
            <p className="text-gray-300 text-base md:text-lg mb-8 max-w-lg leading-relaxed">
              {homeData?.bio || "I'm a passionate web developer and designer who loves creating amazing digital experiences."}
            </p>
            {homeData?.resume_file && (
              <a
                href={homeData.resume_file}
                target="_blank"
                rel="noreferrer"
                className="bg-[#3b82f6] hover:bg-blue-600 text-white font-medium px-6 py-3 rounded-xl shadow-lg transition duration-200 inline-block"
              >
                Download Resume
              </a>
            )}
          </div>

          <div className="flex flex-col items-center justify-center">
            <div className="relative w-64 h-64 md:w-80 md:h-80 rounded-full p-2 bg-gradient-to-tr from-blue-600 to-indigo-400 shadow-[0_0_35px_rgba(59,130,246,0.4)] mb-8">
              <img
                src={getProfileImage()}
                alt="Profile Avatar"
                className="w-full h-full object-cover rounded-full bg-[#18181b]"
              />
            </div>
            {/* UPDATED Social Icons using generic placeholders */}
            <div className="flex gap-6 text-white text-2xl">
              <a href="https://instagram.com" target="_blank" rel="noreferrer" className="hover:text-blue-400 transition"><Share2 size={28} /></a>
              <a href="https://whatsapp.com" target="_blank" rel="noreferrer" className="hover:text-blue-400 transition"><Phone size={28} /></a>
              <a href="https://github.com" target="_blank" rel="noreferrer" className="hover:text-blue-400 transition"><Code2 size={28} /></a>
              <a href="https://linkedin.com" target="_blank" rel="noreferrer" className="hover:text-blue-400 transition"><User size={28} /></a>
            </div>
          </div>
        </div>
      </section>

      {/* --- 2. PROJECTS SECTION --- */}
      <section id="projects" className="min-h-screen py-24 px-6 md:px-16 flex flex-col justify-center">
        <div className="max-w-6xl mx-auto w-full">
          <h2 className="text-4xl font-bold text-center text-[#3b82f6] mb-16 tracking-wide">My Projects</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {projects.map((project) => (
              <div key={project.id} className="bg-white text-black p-8 rounded-2xl shadow-xl flex flex-col justify-between">
                <div>
                  <h3 className="text-2xl font-bold mb-4">{project.title}</h3>
                  <p className="text-gray-700 text-sm md:text-base leading-relaxed mb-6">{project.description}</p>
                </div>
                <div className="flex gap-4">
                  {project.github_url && (
                    <a
                      href={project.github_url}
                      target="_blank"
                      rel="noreferrer"
                      className="bg-[#1f2937] hover:bg-black text-white px-6 py-2.5 rounded-lg font-medium text-sm transition"
                    >
                      GitHub
                    </a>
                  )}
                  {project.live_demo_url && (
                    <a
                      href={project.live_demo_url}
                      target="_blank"
                      rel="noreferrer"
                      className="bg-[#5370ef] hover:bg-blue-700 text-white px-6 py-2.5 rounded-lg font-medium text-sm transition"
                    >
                      Live Demo
                    </a>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* --- 3. SKILLS SECTION --- */}
      <section id="skills" className="min-h-screen py-24 px-6 md:px-16 flex flex-col justify-center">
        <div className="max-w-7xl mx-auto w-full">
          <h2 className="text-4xl font-bold text-center text-[#3b82f6] mb-16 tracking-wide">My Skills</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-6">
            {skills.map((cat) => (
              <div key={cat.id} className="bg-[#5370ef] text-white p-6 rounded-2xl shadow-lg flex flex-col">
                <h3 className="font-bold text-lg mb-4 border-b border-blue-400 pb-2">{cat.name}</h3>
                <ul className="space-y-2 text-sm">
                  {cat.skills.map((skill) => (
                    <li key={skill.id} className="flex items-center gap-2">
                      <span className="w-1.5 h-1.5 bg-white rounded-full"></span>
                      {skill.name}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* --- 4. ABOUT SECTION --- */}
      <section id="about" className="min-h-screen py-24 px-6 md:px-16 flex flex-col justify-center">
        <div className="max-w-4xl mx-auto w-full bg-[#18181b] border border-gray-800 p-8 md:p-12 rounded-3xl shadow-2xl">
          <h2 className="text-3xl md:text-4xl font-bold text-[#3b82f6] mb-8">About Me</h2>

          <div className="space-y-4 text-gray-300 text-sm md:text-base leading-relaxed mb-12">
            <p>{aboutData?.bio_paragraph_1 || "Bio loading..."}</p>
            <p>{aboutData?.bio_paragraph_2}</p>
            <p>{aboutData?.bio_paragraph_3}</p>
            <p>{aboutData?.bio_paragraph_4}</p>
          </div>

          <h3 className="text-2xl font-bold text-[#3b82f6] mb-4">Education</h3>
          <div className="border-l-2 border-blue-500 pl-4 py-1">
            <h4 className="font-bold text-lg">{aboutData?.education_title || "Education loading..."}</h4>
            <p className="text-gray-300 text-sm">{aboutData?.education_institution}</p>
            <p className="text-gray-400 text-xs mt-1">{aboutData?.education_years}</p>
          </div>
        </div>
      </section>

      {/* --- 5. CONTACT SECTION --- */}
      <section id="contact" className="min-h-screen py-24 px-6 md:px-16 flex flex-col justify-center">
        <div className="max-w-3xl mx-auto w-full text-center">
          <h2 className="text-4xl font-bold text-[#3b82f6] mb-2">Contact Me</h2>
          <p className="text-gray-400 text-sm md:text-base mb-10">Whether it's a new project, a collaboration, or just to say hi — I'd love to hear from you!</p>

          {submitted && (
            <div className="mb-6 p-4 bg-green-900/55 border border-green-500 text-green-200 rounded-xl">
              Your message has been successfully sent!
            </div>
          )}

          <form onSubmit={handleContactSubmit} className="space-y-6 text-left">
            <input
              type="text"
              required
              placeholder="Your Name"
              value={contactForm.name}
              onChange={(e) => setContactForm({ ...contactForm, name: e.target.value })}
              className="w-full bg-[#121212] border border-gray-800 rounded-xl p-4 text-white placeholder-gray-500 focus:outline-none focus:border-blue-500"
            />
            <input
              type="text"
              required
              placeholder="Your Subject"
              value={contactForm.subject}
              onChange={(e) => setContactForm({ ...contactForm, subject: e.target.value })}
              className="w-full bg-[#121212] border border-gray-800 rounded-xl p-4 text-white placeholder-gray-500 focus:outline-none focus:border-blue-500"
            />
            <textarea
              rows="5"
              required
              placeholder="Your Message..."
              value={contactForm.message}
              onChange={(e) => setContactForm({ ...contactForm, message: e.target.value })}
              className="w-full bg-[#121212] border border-gray-800 rounded-xl p-4 text-white placeholder-gray-500 focus:outline-none focus:border-blue-500 resize-none"
            ></textarea>
            <button
              type="submit"
              className="w-full bg-[#5370ef] hover:bg-blue-600 text-white font-medium py-4 rounded-xl transition shadow-lg text-center"
            >
              Send Message
            </button>
          </form>

          {/* Contact Details Footer Info */}
          <div className="flex flex-col md:flex-row justify-center items-center gap-8 mt-12 text-gray-300 text-sm">
            <div className="flex items-center gap-3">
              <Phone size={20} className="text-blue-500" />
              <span>{contactInfo?.phone || "+91 9220460134"}</span>
            </div>
            <div className="flex items-center gap-3">
              <Mail size={20} className="text-blue-500" />
              <span>{contactInfo?.email || "karkisahil2003@gmail.com"}</span>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}
